CREATE OR REPLACE FUNCTION check_home_booking_rules() RETURNS TRIGGER AS $$ DECLARE v_salon_radius NUMERIC; v_pro_max_distance NUMERIC; v_pro_home_fee NUMERIC; v_pro_home_fee_type TEXT; v_pro_home_fee_per_km NUMERIC; v_home_fee_type TEXT; v_home_fee_amount NUMERIC; v_home_fee_per_km NUMERIC; v_salon_lat NUMERIC; v_salon_lng NUMERIC; v_distance NUMERIC; v_effective_radius NUMERIC; v_expected_fee NUMERIC; BEGIN IF NEW.service_location != 'home' THEN NEW.client_lat := NULL; NEW.client_lng := NULL; NEW.travel_fee := 0; RETURN NEW; END IF; IF NEW.client_lat IS NULL OR NEW.client_lng IS NULL THEN RAISE EXCEPTION 'Para atendimento a domicílio, as coordenadas do cliente (client_lat, client_lng) são obrigatórias.'; END IF; SELECT ts.home_service_radius_km, ts.home_fee_type, ts.home_fee_amount, ts.home_fee_per_km, ts.latitude, ts.longitude INTO v_salon_radius, v_home_fee_type, v_home_fee_amount, v_home_fee_per_km, v_salon_lat, v_salon_lng FROM tenant_settings ts WHERE ts.tenant_id = NEW.tenant_id; SELECT max_home_distance_km, home_fee, home_fee_type, home_fee_per_km INTO v_pro_max_distance, v_pro_home_fee, v_pro_home_fee_type, v_pro_home_fee_per_km FROM professionals WHERE id = NEW.professional_id AND tenant_id = NEW.tenant_id; v_distance := haversine_distance_km(v_salon_lat, v_salon_lng, NEW.client_lat, NEW.client_lng); v_effective_radius := CASE WHEN v_pro_max_distance > 0 THEN LEAST(v_pro_max_distance, v_salon_radius) ELSE v_salon_radius END; IF v_effective_radius > 0 AND v_distance > (v_effective_radius + 2.5) THEN RAISE EXCEPTION 'A distância (% km) excede o raio de cobertura permitido (% km).', round(v_distance, 1), round(v_effective_radius, 1); END IF; IF v_pro_home_fee_type = 'per_km' THEN v_expected_fee := v_distance * COALESCE(v_pro_home_fee_per_km, 0); ELSIF v_pro_home_fee > 0 THEN v_expected_fee := v_pro_home_fee; ELSE IF v_home_fee_type = 'fixed' THEN v_expected_fee := v_home_fee_amount; ELSIF v_home_fee_type = 'per_km' THEN v_expected_fee := v_distance * v_home_fee_per_km; ELSE v_expected_fee := 0; END IF; END IF; IF ABS(NEW.travel_fee - v_expected_fee) > 1.00 THEN RAISE EXCEPTION 'Taxa de deslocamento incorreta. Esperado: %, Recebido: %.', v_expected_fee, NEW.travel_fee; END IF; NEW.travel_fee := v_expected_fee; RETURN NEW; END; $$ LANGUAGE plpgsql;
